<script setup lang="ts">import type { GameLaunchState } from "@arcade/shared"; defineProps<{ state: GameLaunchState; message?: string }>(); const emit = defineEmits<{ retry: []; back: []; fullscreen: [] }>(); const labels: Record<GameLaunchState, string> = { requested: "已请求启动", validating: "正在验证版本", preparing: "正在准备资源", loading: "正在加载游戏", ready: "游戏已就绪", running: "游戏运行中", blocked: "启动被阻止", paused: "游戏暂时维护", failed: "启动失败", offline: "当前离线" };</script><template><section class="launch-progress-panel" :class="`launch-${state}`"><div class="launch-progress-top"><span class="portal-eyebrow">启动阶段</span><strong>{{ labels[state] }}</strong></div><div class="launch-progress-track"><i :style="{ width: ['requested','validating','preparing','loading'].includes(state) ? '55%' : state === 'ready' || state === 'running' ? '100%' : '28%' }"></i></div><p>{{ message || (state === "loading" ? "第三方游戏可能无法提供精确进度，我们会在资源完成后继续。" : "平台只会根据服务端返回的受控配置启动游戏。") }}</p><div class="launch-progress-actions"><button class="portal-secondary-button" type="button" @click="emit('back')">返回详情</button><button v-if="state === 'failed' || state === 'offline'" class="portal-secondary-button" type="button" @click="emit('retry')">重试</button><button v-if="state === 'running'" class="portal-secondary-button" type="button" @click="emit('fullscreen')">全屏</button></div></section></template>
